-- Removes the smoke-test data from the admin portal database.
--
-- Everything below was generated by test runs on 12–13 Oct 2026: the rows are
-- named "Test Health"/"Test Life" or carry an epoch-timestamp suffix
-- ("Star Health 1791848231981", "op179188874817868@coveresy.com").
--
-- Run:  cd portal && npx wrangler d1 execute coveresy-ops --remote --file=./scripts/purge-test-data.sql
--
-- KEPT deliberately:
--   users: admin@coveresy.com      — the only real login; deleting it locks everyone out
--   document_rules (6), settings (7) — configuration from migration 0002, not test data
--   partner_accounts (1)            — the live partner portal login
--   partner_applications, quote_requests — real tables, already empty
--
-- Order matters: applications go first because application_documents,
-- status_history, payouts and payout_events cascade from them, and because
-- users cannot be removed while an application still references created_by.

DELETE FROM applications;     -- 26 rows: "Test Health" x13, "Test Life" x13
DELETE FROM payout_rules;     -- 13 rows, every one scoped to a test insurer/partner
DELETE FROM partners;         -- 13 rows: "Arham Secure <epoch>"
DELETE FROM insurers;         -- 13 rows: "Star Health <epoch>"
DELETE FROM audit_logs;       -- 222 rows, all of it test activity
DELETE FROM login_attempts;   -- test sign-in attempts

-- 13 generated operator accounts; their sessions cascade away with them.
DELETE FROM users WHERE role = 'operator' AND email LIKE 'op%@coveresy.com';
